'use strict';
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format((v||0)/100);
const date=v=>new Date(v).toLocaleDateString('en-US',{month:'short',day:'numeric'});
const clock=v=>new Date(v).toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'});
const paths={shield:'M12 3 21 7v6c0 5-9 9-9 9s-9-4-9-9V7z M8 12l3 3 5-6',grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',cases:'M8 5V3h8v2 M3 6h18v15H3z M3 11h18 M10 11v3h4v-3',book:'M4 3h13l3 3v15H4z M8 8h7 M8 12h8 M8 16h5',mail:'M3 5h18v14H3z M3 5l9 8 9-8',chart:'M4 20V10 M10 20V4 M16 20v-7 M22 20H1',team:'M16 21v-2c0-3-2-5-5-5H7c-3 0-5 2-5 5v2 M9 10a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M17 3a4 4 0 0 1 0 8 M22 21v-2c0-2-1-4-3-5',settings:'M9 3h6l1 4 4 2v6l-4 2-1 4H9l-1-4-4-2V9l4-2z M15 12a3 3 0 1 0-6 0 3 3 0 0 0 6 0',plus:'M12 5v14 M5 12h14',arrow:'M5 12h14 M14 7l5 5-5 5',check:'M5 12l4 4L19 6',lock:'M6 10V7a6 6 0 0 1 12 0v3 M4 10h16v12H4z M12 14v4',logout:'M9 3H3v18h6 M11 12h10 M17 8l4 4-4 4',search:'M16 16l5 5 M18 10a8 8 0 1 0-16 0 8 8 0 0 0 16 0',pause:'M8 4v16 M16 4v16',play:'M6 3l15 9-15 9z',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',user:'M20 21v-2a7 7 0 0 0-14 0v2 M16 6a4 4 0 1 0-8 0 4 4 0 0 0 8 0',activity:'M2 12h5l3-9 4 18 3-9h5',dollar:'M12 2v20 M17 5H9a4 4 0 0 0 0 8h6a3 3 0 0 1 0 6H6',chevron:'M9 5l7 7-7 7',info:'M12 8h.01 M12 11v6 M22 12a10 10 0 1 0-20 0 10 10 0 0 0 20 0',folder:'M2 6V3h7l3 3h10v15H2z',send:'M22 2 9 15 M22 2l-7 20-6-7-7-6z'};
const icon=(name,cls='')=>`<svg class="${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.info}"/></svg>`;
const brand=()=>`<div class="brand"><span class="brand-mark">${icon('shield')}</span>refundguard<span class="brand-period">.</span></div>`;
const badge=status=>`<span class="badge ${esc(status)}"><span class="dot ${['blocked','denied'].includes(status)?'paused':''}"></span>${esc(({processed:'Approved',new:'New case',review:'Needs review',blocked:'Blocked',denied:'Denied',processing:'Processing'})[status]||status)}</span>`;
const state={user:null,csrf:null,mode:'Local simulation',authority:true,page:'overview',filter:'all',cases:[],setupToken:null,inviteToken:null};
let toastTimer,modalFocus;
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500)}
async function api(path,method='GET',body){const res=await fetch('/api'+path,{method,credentials:'same-origin',headers:{...(method!=='GET'?{'Content-Type':'application/json','X-CSRF-Token':state.csrf||''}:{})},...(body!==undefined?{body:JSON.stringify(body)}:method!=='GET'?{body:'{}'}:{})});let data;try{data=await res.json()}catch{throw Error('The server did not return a valid response')};if(!res.ok){if(res.status===401&&state.user&&!path.startsWith('/auth/mfa/')){state.user=null;authScreen('login')};const message=Array.isArray(data.detail)?data.detail.map(e=>e.msg).join('; '):data.detail;throw Error(message||'The request could not be completed')};return data}
const isStaff=()=>state.user?.role!=='customer';
const canControl=()=>['admin','supervisor'].includes(state.user?.role);
const initials=name=>name.split(' ').map(s=>s[0]).slice(0,2).join('').toUpperCase();
const notice=(text,warn=false)=>`<div class="notice ${warn?'warn':''}">${icon('info')}<div>${text}</div></div>`;
function heading(eyebrow,title,subtitle,action=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="subtitle">${subtitle}</p></div>${action}</div>`}
function empty(text,button=''){return `<div class="empty">${icon('cases')}<p>${text}</p>${button?`<div class="spacer"></div>${button}`:''}</div>`}
function shell(){const nav=[['overview','grid','Overview'],['cases','cases','Cases'],...(isStaff()?[['knowledge','book','Knowledge base'],['inbox','mail','Inbox'],['assurance','shield','Assurance'],['team','team','Team']]:[]),['settings','settings','Settings']];$('#app').innerHTML=`<div class="app-shell"><aside class="sidebar">${brand()}<div class="workspace-label">Workspace</div><nav class="nav" aria-label="Main navigation">${nav.map(([id,ico,title])=>`<a href="#${id}" data-page="${id}" class="${state.page===id?'active':''}">${icon(ico)}${title}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="workspace-card"><div class="eyebrow">Built with boundaries</div><p>Five specialist agents.<br>One accountable workflow.</p></div><div class="person"><div class="avatar">${esc(initials(state.user.name))}</div><div><div class="person-name">${esc(state.user.name)}</div><small>${esc(state.user.role)}</small></div><button data-action="logout" aria-label="Sign out">${icon('logout')}</button></div><button class="mobile-nav-button" data-action="logout">Sign out</button></div></aside><main class="main"><header class="topbar"><div class="breadcrumb">Team workspace <span>/</span><span>${esc(nav.find(n=>n[0]===state.page)?.[2]||'Overview')}</span></div><div class="top-status"><span class="dot ${state.authority?'':'paused'}"></span>${state.authority?'Agents active':'Authority paused'}<span class="sandbox-pill">SYNTHETIC DATA</span></div></header><div class="content" id="content"><div class="progress-text"><span class="spinner"></span>Loading workspace…</div></div></main></div>`}
async function render(){if(!state.user)return;const security=await api('/auth/me');if(security.mfa_required)return mfaScreen(security.mfa_enabled);state.mfaEnabled=security.mfa_enabled;const valid=['overview','cases','settings',...(isStaff()?['knowledge','inbox','assurance','team']:[])];if(!valid.includes(state.page))state.page='overview';shell();try{await ({overview:overviewPage,cases:casesPage,knowledge:knowledgePage,inbox:inboxPage,assurance:assurancePage,team:teamPage,settings:settingsPage}[state.page])()}catch(e){if($('#content'))$('#content').innerHTML=`<div class="error-page"><h2>We couldn’t load this view</h2><p class="subtitle">${esc(e.message)}</p><div class="spacer"></div><button class="btn" data-action="refresh">Try again</button></div>`}}
function footer(){return `<p class="footer-note">COEN 296 · AI Governance & Cybersecurity · RefundGuard<br>All customer records, financial activity, and email delivery are simulated.</p>`}
async function overviewPage(){const [d,cases]=await Promise.all([api('/dashboard'),api('/cases')]);state.cases=cases;state.authority=d.authority_active;const counts=d.counts,total=Object.values(counts).reduce((a,b)=>a+b,0),review=(counts.review||0)+(counts.blocked||0);$('#content').innerHTML=heading('Your support command center','A little more oversight.','Keep customer support moving, with the right controls in place.',`<button class="btn primary" data-action="new-case">${icon('plus')}New case</button>`)+`<section class="hero"><div class="hero-copy"><div class="eyebrow">Responsible by design</div><h2>Helpful agents. Clear boundaries.</h2><p>From the first customer message to the final refund, every consequential action is checked, scoped, and recorded.</p><div class="button-row"><a class="btn primary" href="#cases">Explore cases ${icon('arrow')}</a>${isStaff()?'<a class="btn" href="#assurance">View assurance</a>':''}</div></div><div class="hero-art">${icon('shield','shield')}<div class="vertical"><span class="hero-chip">${icon('check')}$100 transaction limit</span><span class="hero-chip">${icon('check')}$500 weekly budget</span><span class="hero-chip">${icon('check')}Independent authorization</span></div></div></section><div class="stats"><div class="stat"><div class="stat-top">Total cases ${icon('cases')}</div><strong>${total}</strong><div class="stat-foot">Across your ${isStaff()?'workspace':'account'}</div></div><div class="stat"><div class="stat-top">Approved refunds ${icon('check')}</div><strong>${counts.processed||0}</strong><div class="stat-foot"><em>Verified at execution</em></div></div><div class="stat"><div class="stat-top">Needs attention ${icon('activity')}</div><strong>${review}</strong><div class="stat-foot">Held for human review</div></div><div class="stat"><div class="stat-top">${isStaff()?'Weekly refunds':'Transaction cap'} ${icon('dollar')}</div><strong>${money(isStaff()?d.weekly_spent_cents:10000)}</strong><div class="stat-foot">${isStaff()?`${money(Math.max(0,50000-d.weekly_spent_cents))} remaining of $500`:'Maximum autonomous refund'}</div></div></div><section><div class="section-head"><div><h2>Recent cases</h2><p>A clear view of what’s happening.</p></div><a class="text-link" href="#cases">View all cases ${icon('arrow')}</a></div><div class="panel">${caseTable(cases.slice(0,5))}</div></section><div class="bottom-grid"><section class="panel panel-pad"><div class="section-head"><div><h3>Your agent workflow</h3><p>Specialist roles, connected by an orchestrator.</p></div><span class="badge">5 agents</span></div><div class="pipeline">${[['Intake','cases'],['Records','folder'],['Refunds','dollar'],['Email','mail'],['Reporting','chart']].map(([name,ico],i)=>`${i?'<div class="pipeline-line"></div>':''}<div class="pipeline-item"><div class="pipeline-node">${icon(ico)}</div>${name}</div>`).join('')}</div><div class="spacer"></div>${notice(d.mode==='Local simulation'?'Local simulation is active. Vector retrieval and execution controls work; no LLM is called.':'Live LLM mode is active. Agent proposals still pass through independent execution controls.')}</section><section class="panel panel-pad"><div class="section-head"><div><h3>Workspace activity</h3><p>Recent actions and control decisions.</p></div>${icon('activity')}</div>${d.events.length?d.events.slice(0,4).map(eventRow).join(''):empty('Your activity will appear here.')}</section></div>${footer()}`}
function caseTable(cases){if(!cases.length)return empty('Your first case starts here. Submit a synthetic refund request to see the workflow in action.');return `<div class="table-scroll"><table><thead><tr><th>Case / customer</th><th>Request</th><th>Amount</th><th>Status</th><th>Created</th><th></th></tr></thead><tbody>${cases.map(c=>`<tr class="clickable" data-case="${esc(c.id)}"><td><button class="cell-primary" data-case="${esc(c.id)}">${esc(c.customer_name)}</button><div class="cell-secondary case-id">${esc(c.id)}</div></td><td><div>${esc(c.product)}</div><div class="cell-secondary">${esc(c.reason_code.replaceAll('_',' '))}</div></td><td class="cell-primary">${money(c.amount_cents)}</td><td>${badge(c.status)}</td><td class="muted">${date(c.created_at)}</td><td>${icon('chevron')}</td></tr>`).join('')}</tbody></table></div>`}
function eventRow(e){return `<div class="event"><div class="event-icon">${icon(e.action.includes('auth')?'lock':e.action.includes('refund')?'dollar':'activity')}</div><div><p>${esc(e.action.replaceAll('.',' · ').replaceAll('_',' '))}</p><small>${esc(e.case_id||'Workspace event')}</small></div><time>${clock(e.timestamp)}</time></div>`}
async function casesPage(){state.cases=await api('/cases');$('#content').innerHTML=heading('Customer support','Every case, accounted for.','Submit, review, and follow each request through its decision.',`<button class="btn primary" data-action="new-case">${icon('plus')}New case</button>`)+`<div class="toolbar"><div class="tabs" role="group" aria-label="Filter cases">${[['all','All cases'],['new','New'],['processed','Approved'],['review','Needs review'],['denied','Denied']].map(([k,n])=>`<button class="tab ${state.filter===k?'active':''}" data-filter="${k}">${n}<span class="count">${k==='all'?state.cases.length:state.cases.filter(c=>k==='review'?['review','blocked'].includes(c.status):c.status===k).length}</span></button>`).join('')}</div><input id="case-search" class="filter-input" aria-label="Search cases" placeholder="Search customer or case…"></div><div class="panel" id="case-table"></div>${footer()}`;filterCases()}
function filterCases(){const q=($('#case-search')?.value||'').toLowerCase();const rows=state.cases.filter(c=>(state.filter==='all'||(state.filter==='review'?['review','blocked'].includes(c.status):c.status===state.filter))&&`${c.customer_name} ${c.id} ${c.product}`.toLowerCase().includes(q));$('#case-table').innerHTML=caseTable(rows)}
function modal(title,body,wide=false){modalFocus=document.activeElement;$('#dialog-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><h2 id="modal-title">${esc(title)}</h2><button class="modal-close" data-action="close-modal" aria-label="Close dialog">×</button></div><div class="modal-body">${body}</div></section></div>`;setTimeout(()=>$('.modal input,.modal select,.modal textarea,.modal button')?.focus(),0)}
function closeModal(){$('#dialog-root').innerHTML='';modalFocus?.focus?.()}
async function newCase(){const orders=await api('/orders');const available=orders.filter(o=>!o.case_id);modal('New refund case',available.length?`<form id="new-case-form"><div class="form-grid"><div class="field full"><label for="order-id">Purchase</label><select id="order-id" name="order_id" required>${available.map(o=>`<option value="${esc(o.id)}" data-cents="${o.amount_cents}">${esc(o.customer_name)} · ${esc(o.product)} · ${money(o.amount_cents)}</option>`).join('')}</select></div><div class="field"><label for="amount">Refund amount ($)</label><input id="amount" name="amount" type="number" min="0.01" step="0.01" max="100000" value="${(available[0].amount_cents/100).toFixed(2)}" required></div><div class="field"><label for="reason">Reason</label><select id="reason" name="reason_code"><option value="damaged">Item damaged</option><option value="not_received">Not received</option><option value="wrong_item">Wrong item</option><option value="other">Other / human review</option></select></div><div class="field full"><label for="request-message">Customer message</label><textarea id="request-message" name="message" required maxlength="6000" placeholder="Describe what happened and what the customer is asking for…"></textarea></div></div><div class="spacer"></div>${notice('A request creates a case. It does not automatically authorize a refund. The assigned workflow checks eligibility and authority.')}<div class="form-error" id="form-error"></div><div class="modal-foot"><button type="button" class="btn" data-action="close-modal">Cancel</button><button class="btn primary" type="submit">Create case ${icon('arrow')}</button></div></form>`:empty('Every existing purchase already has a case. Team members can add a synthetic purchase below.',isStaff()?'<button class="btn primary" data-action="new-order">Add synthetic purchase</button>':''))}
async function showCase(cid){const d=await api('/cases/'+encodeURIComponent(cid)),c=d.case;modal(c.id,`<div class="section-head"><div><h2>${esc(c.customer_name)}</h2><p>${esc(c.product)} · ${esc(c.order_id)}</p></div>${badge(c.status)}</div><div class="detail-grid"><div class="stack"><div class="panel panel-pad"><dl class="detail-list"><div><dt>Requested amount</dt><dd>${money(c.amount_cents)}</dd></div><div><dt>Refund reason</dt><dd>${esc(c.reason_code.replaceAll('_',' '))}</dd></div><div><dt>Created</dt><dd>${date(c.created_at)}</dd></div><div><dt>Supervisor state</dt><dd>${esc(c.supervisor)}</dd></div></dl><div class="divider"></div><h3>Customer message</h3><p class="body-copy request-details">${esc(c.message)}</p>${c.rationale?`<div class="divider"></div><h3>Decision reason</h3><p class="body-copy request-details">${esc(c.rationale)}</p>`:''}</div>${c.summary?`<div class="notice">${icon('info')}<div>${esc(c.summary)}</div></div>`:''}<div><div class="section-head"><h3>Case mailbox</h3><button class="text-link" data-action="add-message" data-id="${esc(cid)}">Add incoming email ${icon('plus')}</button></div><div class="panel">${d.messages.length?d.messages.map(m=>`<div class="message"><div class="message-top"><h3>${esc(m.subject)}</h3><span class="badge ${esc(m.direction)}">${esc(m.direction)}</span></div><p>${esc(m.body)}</p><div class="cell-secondary">${clock(m.created_at)} · ${esc(m.recipient)}</div></div>`).join(''):empty('No messages yet.')}</div></div></div><div class="stack">${isStaff()?`<div class="panel panel-pad"><h3>Agent workflow</h3><p class="subtitle">The LLM proposes. Execution controls decide.</p><div class="spacer"></div>${['processed','denied'].includes(c.status)?notice(c.status==='processed'?'A refund was executed and recorded in the ledger.':'This case is denied.'):c.status==='processing'?'<p class="progress-text"><span class="spinner"></span>Processing this case…</p>':`<button class="btn primary" data-action="run-case" data-id="${esc(cid)}">${icon('play')}Run agent workflow</button>`}${canControl()&&c.status!=='processed'?`<div class="divider"></div><h3>Supervisor decision</h3><p class="subtitle">Approval preserves the autonomous refund caps.</p><div class="spacer"></div><div class="button-row"><button class="btn small" data-supervisor="approved" data-id="${esc(cid)}">Approve review</button><button class="btn small danger" data-supervisor="denied" data-id="${esc(cid)}">Deny</button></div>`:''}</div><div class="panel panel-pad"><div class="section-head"><h3>Agent activity</h3><span class="badge">${d.traces.length} events</span></div>${d.traces.length?d.traces.map(t=>`<div class="trace"><div class="title"><h3>${esc(t.agent)}</h3><small>${clock(t.created_at)}</small></div><div class="cell-secondary">${esc(t.operation.replaceAll('_',' '))}</div><details><summary>Inspect evidence</summary><pre>${esc(JSON.stringify(JSON.parse(t.result),null,2))}</pre></details></div>`).join(''):empty('Run the workflow to inspect retrieval sources, recommendations, and execution decisions.')}</div>`:notice('Your request is visible to the support team. Its outcome will appear here.')}</div></div>`,true)}
async function knowledgePage(){const docs=await api('/knowledge');state.docs=docs;$('#content').innerHTML=heading('Grounded in your policies','Knowledge, with provenance.','Versioned documents and customer-scoped vector retrieval.',canControl()?`<button class="btn primary" data-action="add-document">${icon('plus')}Add document</button>`:'')+notice(state.mode==='Local simulation'?'Local hash vectors provide lexical similarity in SQLite. Switch to API embeddings for learned semantic retrieval.':'Learned API embeddings are stored in SQLite and searched with sqlite-vec. Customer scope is applied before context is returned.')+`<div class="spacer"></div><div class="section-head"><h2>Indexed documents</h2><span class="muted">${docs.filter(d=>d.active).length} active sources</span></div><div class="card-grid">${docs.map(d=>`<article class="document-card"><div class="section-head"><div class="doc-icon">${icon(d.kind==='policy'?'book':'user')}</div><span class="badge ${d.active?'active':'review'}">${d.active?'Active':d.review_status==='pending'?'Awaiting review':d.review_status==='rejected'?'Rejected':'Superseded'}</span></div><div><h3>${esc(d.title)}</h3><div class="cell-secondary">${esc(d.kind==='policy'?'Workspace policy':d.customer_id)}</div></div><p>${esc(d.content)}</p>${policyActions(d)}<div class="doc-meta"><span>v${d.version} · ${d.chunks} vectors</span><button class="text-link" data-document="${esc(d.id)}">Read source ${icon('arrow')}</button></div></article>`).join('')}</div><div class="spacer"></div><section class="panel panel-pad"><div class="section-head"><div><h2>Test scoped retrieval</h2><p>Search in the context of an authorized customer case.</p></div>${icon('search')}</div><form id="search-form"><div class="form-grid"><div class="field"><label for="search-case">Case ID</label><input id="search-case" name="case_id" required placeholder="RG-…"></div><div class="field"><label for="retrieval-query">Question</label><input id="retrieval-query" name="query" required placeholder="What is the refund policy?"></div></div><div class="spacer"></div><button class="btn" type="submit">${icon('search')}Search documents</button><div class="form-error" id="form-error"></div></form><div id="search-results"></div></section>${footer()}`}
async function addDocument(){const profiles=await api('/profiles');modal('Add knowledge document',`<form id="document-form"><div class="form-grid"><div class="field full"><label for="doc-title">Document title</label><input id="doc-title" name="title" required maxlength="160" placeholder="Refund policy or customer case note"></div><div class="field"><label for="doc-kind">Document type</label><select id="doc-kind" name="kind"><option value="policy">Workspace policy</option><option value="customer">Customer document</option></select></div><div class="field"><label for="doc-customer">Customer scope</label><select id="doc-customer" name="customer_id"><option value="">Not applicable to policies</option>${profiles.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('')}</select></div><div class="field full"><label for="doc-file">Import a text or Markdown file (optional)</label><input id="doc-file" type="file" accept=".txt,.md,text/plain,text/markdown"></div><div class="field full"><label for="doc-content">Document content</label><textarea id="doc-content" name="content" required minlength="10" maxlength="40000" rows="9" placeholder="Paste the source document…"></textarea><small>Policy uploads await approval by a different administrator or supervisor. Reusing a title and scope creates a new version. Document text cannot change trusted refund controls.</small></div></div><div class="form-error" id="form-error"></div><div class="modal-foot"><button class="btn" type="button" data-action="close-modal">Cancel</button><button class="btn primary" type="submit">Index document ${icon('arrow')}</button></div></form>`)}
async function inboxPage(){const messages=await api('/messages');$('#content').innerHTML=heading('Customer communication','An inbox you can inspect.','Incoming requests, trusted outcome notices, and drafts awaiting review.')+notice('All email stays inside this local mock mailbox. Draft text is never automatically delivered to an external address.')+`<div class="spacer"></div><div class="panel">${messages.length?messages.map(m=>`<div class="message"><div class="message-top"><div><button class="cell-primary text-link" data-case="${esc(m.case_id)}">${esc(m.subject)}</button><div class="cell-secondary">${esc(m.customer_name)} · ${esc(m.case_id)}</div></div><div><span class="badge ${esc(m.direction)}">${esc(m.direction)}</span></div></div><p>${esc(m.body)}</p><div class="cell-secondary">${date(m.created_at)} at ${clock(m.created_at)} · ${esc(m.recipient)}</div></div>`).join(''):empty('Create a case to receive your first mock email.')}</div>${footer()}`}
async function assurancePage(){const d=await api('/reports');state.reports=d;const b=d.benchmarks[0]?JSON.parse(d.benchmarks[0].results):null;$('#content').innerHTML=heading('Evidence over assumptions','Trust, backed by checks.','Inspect what agents attempted, what controls allowed, and what actually executed.',canControl()?`<button class="btn primary" data-action="run-benchmarks">${icon('play')}Run control checks</button>`:'')+notice('These isolated checks exercise execution controls. Live LLM red teaming and the assigned CWEval benchmark still need separate evaluation.')+`<div class="stats"><div class="stat"><div class="stat-top">Functional pass rate ${icon('check')}</div><strong>${b?Math.round(b.functional_pass_rate*100)+'%':'—'}</strong><div class="stat-foot">${b?'Latest isolated check run':'Run checks to collect evidence'}</div></div><div class="stat"><div class="stat-top">Joint pass rate ${icon('shield')}</div><strong>${b?Math.round(b.joint_pass_rate*100)+'%':'—'}</strong><div class="stat-foot">Functionality + boundary controls</div></div><div class="stat"><div class="stat-top">Refund decisions ${icon('dollar')}</div><strong>${d.decisions.length}</strong><div class="stat-foot">Recorded control outcomes</div></div><div class="stat"><div class="stat-top">Authority ${icon('lock')}</div><strong>${state.authority?'Active':'Paused'}</strong><div class="stat-foot">Rechecked at execution</div></div></div><section><div class="section-head"><h2>Execution-boundary checks</h2>${canControl()?'<a class="btn small" href="/api/reports/export" download="refundguard-evidence.json">'+icon('download')+'Export evidence</a>':''}</div><div class="panel">${b?`<div class="table-scroll"><table><thead><tr><th>Scenario</th><th>Functionality</th><th>Security</th><th>Observed control</th></tr></thead><tbody>${b.scenarios.map(s=>`<tr><td class="cell-primary">${esc(s.name)}</td><td><span class="badge ${s.functional_pass?'active':'denied'}">${s.functional_pass?'PASS':'FAIL'}</span></td><td><span class="badge ${s.security_pass?'active':'denied'}">${s.security_pass?'PASS':'FAIL'}</span></td><td class="mono">${esc(s.observed)}</td></tr>`).join('')}</tbody></table></div>`:empty('Run the isolated control suite. It uses disposable data and leaves customer balances unchanged.')}</div></section><div class="bottom-grid"><section class="panel panel-pad"><div class="section-head"><h2>Refund outcomes</h2><span class="badge">${d.cases.length} cases</span></div>${d.cases.length?d.cases.map(c=>`<div class="event"><div>${badge(c.status)}</div><div><button class="text-link" data-case="${esc(c.id)}">${esc(c.id)} · ${money(c.amount_cents)}</button><small>${esc(c.rationale||'Awaiting workflow')}</small></div></div>`).join(''):empty('No case outcomes yet.')}</section><section class="panel panel-pad"><div class="section-head"><h2>Audit timeline</h2>${icon('activity')}</div>${d.events.slice(0,14).map(eventRow).join('')}</section></div>${canControl()?await securityPanel():''}${footer()}`}
async function teamPage(){const d=await api('/team');$('#content').innerHTML=heading('Your project team','A workspace for all five.','Individual accounts. Explicit roles. No shared passwords.',state.user.role==='admin'?`<div class="button-row"><button class="btn" data-action="shared-admin-link">Shared admin link</button><button class="btn primary" data-action="invite">${icon('plus')}Invite teammate</button></div>`:'')+`<div class="panel"><div class="table-scroll"><table><thead><tr><th>Team member</th><th>Role</th><th>Access</th><th>Joined</th><th></th></tr></thead><tbody>${d.users.map(u=>`<tr><td><div class="profile-row"><div class="avatar">${esc(initials(u.name))}</div><div><div class="cell-primary">${esc(u.name)}</div><div class="cell-secondary">${esc(u.email)}</div></div></div></td><td>${esc(u.role)}</td><td><span class="badge ${u.active?'active':'denied'}">${u.active?'Active':'Disabled'}</span></td><td>${date(u.created_at)}</td><td>${state.user.role==='admin'&&u.id!==state.user.id?`<button class="btn small ${u.active?'danger':''}" data-user="${esc(u.id)}" data-active="${u.active?'false':'true'}">${u.active?'Disable':'Enable'}</button>`:''}</td></tr>`).join('')}</tbody></table></div></div><div class="spacer"></div>${notice('Members manage support cases and inspect evidence. Supervisors also review decisions and pause agents. Administrators manage invitations and account access. Customers can only view their own records.')}<div class="spacer"></div>${d.invites.length?`<section><div class="section-head"><h2>Invitations</h2><p class="muted">Single use · expires after 48 hours</p></div><div class="panel"><div class="table-scroll"><table><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Status</th></tr></thead><tbody>${d.invites.map(i=>`<tr><td>${esc(i.name)}</td><td>${esc(i.email)}</td><td>${esc(i.role)}</td><td><span class="badge">${i.used?'Used / superseded':i.expires<Date.now()/1000?'Expired':'Pending'}</span></td></tr>`).join('')}</tbody></table></div></div></section>`:''}${footer()}`}
function inviteForm(){modal('Invite a teammate',`<form id="invite-form"><div class="form-grid"><div class="field full"><label for="invite-name">Name</label><input id="invite-name" name="name" required maxlength="80" placeholder="Silvia, Alex, Rina, Josephine…"></div><div class="field full"><label for="invite-email">Email address</label><input id="invite-email" name="email" type="email" required autocomplete="email"></div><div class="field full"><label for="invite-role">Role</label><select id="invite-role" name="role"><option value="member">Member — cases and evidence</option><option value="supervisor">Supervisor — decisions and authority</option><option value="admin">Administrator — team access and all controls</option><option value="customer">Customer — own cases only</option></select><small>Choose the least access this person needs. Invitation links are private and expire after 48 hours.</small></div></div><div class="form-error" id="form-error"></div><div class="modal-foot"><button class="btn primary" type="submit">Create invitation ${icon('arrow')}</button></div></form>`)}
async function settingsPage(){const [me,profiles]=await Promise.all([api('/auth/me'),api('/profiles')]);state.mode=me.mode;state.authority=me.authority_active;state.profiles=profiles;$('#content').innerHTML=heading('Workspace preferences','Keep the controls close.','Manage your session, agent authority, and synthetic test data.')+`<div class="settings-grid"><section class="panel panel-pad settings-card"><h2>Agent authority</h2><div class="switch-row"><div><h3>${state.authority?'Agents are active':'Agent actions are paused'}</h3><p>Pause refunds and outbound mock mail.<br>Revocation persists across server restarts.</p></div>${badge(state.authority?'active':'blocked')}</div>${canControl()?`<button class="btn ${state.authority?'danger':'primary'}" data-action="authority">${icon(state.authority?'pause':'play')}${state.authority?'Pause agent authority':'Restore agent authority'}</button>`:notice('A supervisor or administrator can change agent authority.')}</section><section class="panel panel-pad settings-card"><h2>Model & retrieval</h2><div class="spacer"></div><dl class="detail-list"><div><dt>Generation</dt><dd>${esc(me.mode)}</dd></div><div><dt>Vector store</dt><dd>SQLite + sqlite-vec</dd></div><div class="field full"><dt>Embedding space</dt><dd class="mono">${esc(me.embeddings)}</dd></div></dl><div class="spacer"></div>${notice('API credentials are configured on the server only. Local simulation does not call a model or incur API charges.')}</section><section class="panel panel-pad settings-card"><h2>Change your password</h2><p class="subtitle">Changing your password ends all other sessions.</p><form id="password-form"><div class="field"><label for="current-password">Current password</label><input id="current-password" name="current_password" type="password" autocomplete="current-password" required></div><div class="field"><label for="new-password">New password</label><input id="new-password" name="new_password" type="password" autocomplete="new-password" minlength="15" maxlength="128" required><small>Use a unique passphrase with at least 15 characters.</small></div><div class="form-error" id="form-error"></div><button class="btn" type="submit">Update password</button></form></section><section class="panel panel-pad settings-card"><h2>Multi-factor authentication</h2><p>${state.mfaEnabled?'Your authenticator protects sign-in. Keep your recovery codes private.':'Add an authenticator app to protect this account.'}</p>${!state.mfaEnabled?'<button class="btn" data-action="mfa-enroll">Set up authenticator</button>':''}<div class="divider"></div><h2>Your session</h2><p class="subtitle">Signed in as ${esc(state.user.name)}</p><div class="spacer"></div><dl class="detail-list"><div><dt>Account</dt><dd>${esc(state.user.email)}</dd></div><div><dt>Role</dt><dd>${esc(state.user.role)}</dd></div><div><dt>Idle timeout</dt><dd>30 minutes</dd></div><div><dt>Maximum session</dt><dd>8 hours</dd></div></dl><button class="btn" data-action="logout">${icon('logout')}Sign out</button></section></div>${isStaff()?`<div class="spacer"></div><section class="panel panel-pad"><div class="section-head"><div><h2>Synthetic customer records</h2><p>Mock account balances and purchases for testing.</p></div><button class="btn" data-action="new-order">${icon('plus')}Add purchase</button></div><div class="table-scroll"><table><thead><tr><th>Customer</th><th>Mock bank reference</th><th>Balance</th><th>Notes</th><th></th></tr></thead><tbody>${profiles.map(p=>`<tr><td class="cell-primary">${esc(p.name)}</td><td class="mono">${esc(p.bank_ref)}</td><td>${money(p.balance_cents)}</td><td>${esc(p.notes.slice(0,45))}</td><td><button class="text-link" data-profile="${esc(p.id)}">Edit</button></td></tr>`).join('')}</tbody></table></div></section>`:''}${footer()}`}
async function newOrder(){const profiles=await api('/profiles');modal('Add a synthetic purchase',`<form id="order-form"><div class="form-grid"><div class="field full"><label for="order-customer">Customer</label><select id="order-customer" name="customer_id">${profiles.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('')}</select></div><div class="field full"><label for="order-product">Product</label><input id="order-product" name="product" required maxlength="120" placeholder="Demo headphones"></div><div class="field"><label for="order-amount">Purchase amount ($)</label><input id="order-amount" name="amount" type="number" min="0.01" step="0.01" max="100000" required></div><div class="field"><label for="order-age">Purchase age (days)</label><input id="order-age" name="age_days" type="number" min="0" max="365" value="0" required></div></div><div class="form-error" id="form-error"></div><div class="modal-foot"><button class="btn primary" type="submit">Create purchase</button></div></form>`)}
function authScreen(mode='login'){const setup=mode==='setup',team=mode==='team',invite=mode==='invite'||team;$('#app').innerHTML=`<main class="auth-layout"><section class="auth-story">${brand()}<div class="auth-copy"><div class="eyebrow">Customer care. Accountable AI.</div><h1>Good support.<br><span>Sound judgment.</span></h1><p>A shared space for your team to explore how helpful agents become trustworthy systems.</p><div class="auth-points"><div class="auth-point">${icon('shield')}Independent controls on every refund</div><div class="auth-point">${icon('book')}Answers grounded in scoped records</div><div class="auth-point">${icon('activity')}Evidence you can follow from end to end</div></div></div><div class="auth-bottom"><span>COEN 296 · FALL 2026</span><span>BUILT WITH BOUNDARIES</span></div></section><section class="auth-main"><div class="auth-form-wrap"><span class="auth-mode"><span class="dot"></span>Private team workspace</span><h2>${setup?'Make it your workspace.':team?'Join as administrator.':invite?'You’re invited.':'Welcome back.'}</h2><p>${setup?'Create the first administrator account. You’ll invite your team next.':team?'This private link grants full administrator access. Choose your name, email and password. You will then set up an authenticator app.':invite?'Your administrator has reserved an account for you. Choose a private password to join.':'Sign in to your team’s support and assurance workspace.'}</p><form id="auth-form" data-mode="${mode}">${team&&state.teamInvite?notice(`${state.teamInvite.remaining_signups} administrator signup(s) remaining. Expires ${new Date(state.teamInvite.expires*1000).toLocaleString()}.`):''}${setup||team?`<div class="field"><label for="auth-name">Your name</label><input id="auth-name" name="name" required maxlength="80" autocomplete="name"></div>`:''}${!invite||team?`<div class="field"><label for="auth-email">Email address</label><input id="auth-email" name="email" type="email" autocomplete="username" required placeholder="you@example.com"></div>`:''}${setup&&!state.setupToken?`<div class="field"><label for="auth-token">One-time setup key</label><input id="auth-token" name="token" autocomplete="off" required><small>Run <code>./start.sh</code> to open a private setup link, or <code>python manage.py setup-link</code> from the project directory.</small></div>`:''}<div class="field"><label for="auth-password">${setup||invite?'Choose a password':'Password'}</label><input id="auth-password" name="password" type="password" autocomplete="${setup||invite?'new-password':'current-password'}" ${setup||invite?'minlength="15"':''} maxlength="128" required ${!setup&&!invite?'placeholder="Enter your password"':''}>${setup||invite?'<small>Use a unique passphrase with at least 15 characters.</small>':''}</div><div class="form-error" id="auth-error"></div><button type="submit" class="btn primary">${setup?'Create workspace':invite?'Join workspace':'Sign in'} ${icon('arrow')}</button></form><div class="auth-meta">${icon('lock')} Invite-only access · Individual accounts<br>${setup?'Setup can only be completed once.':'Need access? Ask your workspace administrator for an invitation.'}</div></div></section></main>`}
async function doLogout(){await api('/auth/logout','POST');state.user=null;state.csrf=null;closeModal();history.replaceState(null,'',location.pathname);authScreen('login');toast('You’re signed out')}
async function handleAction(action,el){if(action==='mfa-enroll')return mfaScreen(false);if(action==='shared-admin-link'){const d=await api('/team/links','POST');return showAdminLink(d)};if(action==='ack-alert'){await api('/security/alerts/'+el.dataset.id+'/acknowledge','POST');return render()};if(action==='close-modal')return closeModal();if(action==='logout')return doLogout();if(action==='refresh')return render();if(action==='new-case')return newCase();if(action==='add-document')return addDocument();if(action==='invite')return inviteForm();if(action==='new-order')return newOrder();if(action==='authority'){const d=await api('/authority','POST',{active:!state.authority});state.authority=d.active;toast(d.active?'Agent authority restored':'Agent authority paused');return render()};if(action==='run-case'){el.disabled=true;el.innerHTML='<span class="spinner"></span>Running workflow…';try{const d=await api('/cases/'+encodeURIComponent(el.dataset.id)+'/run','POST');toast('Workflow result: '+d.status);await render();await showCase(el.dataset.id)}finally{el.disabled=false}};if(action==='run-benchmarks'){el.disabled=true;el.textContent='Running checks…';await api('/benchmarks/run','POST');toast('Execution-boundary checks completed');return render()};if(action==='add-message'){const id=el.dataset.id;modal('Add incoming mock email',`<form id="message-form" data-id="${esc(id)}"><div class="stack"><div class="field"><label for="mail-subject">Subject</label><input id="mail-subject" name="subject" required maxlength="200"></div><div class="field"><label for="mail-body">Message</label><textarea id="mail-body" name="body" required maxlength="6000"></textarea></div></div><div class="form-error" id="form-error"></div><div class="modal-foot"><button class="btn primary" type="submit">Receive email</button></div></form>`)};if(action==='copy-invite'){await navigator.clipboard.writeText($('#invite-url').value);toast('Private invitation copied')}}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action],[data-case],[data-filter],[data-document],[data-profile],[data-supervisor],[data-user]');if(!el)return;try{if(el.dataset.action)return await handleAction(el.dataset.action,el);if(el.dataset.case)return await showCase(el.dataset.case);if(el.dataset.filter){state.filter=el.dataset.filter;document.querySelectorAll('[data-filter]').forEach(t=>t.classList.toggle('active',t===el));return filterCases()};if(el.dataset.document){const d=state.docs.find(x=>x.id===el.dataset.document);return modal(d.title,`<div class="section-head"><span class="badge">Version ${d.version}</span><span class="case-id">${esc(d.id)}</span></div><p class="body-copy">${esc(d.content)}</p>${policyActions(d)}`)};if(el.dataset.supervisor){await api('/cases/'+encodeURIComponent(el.dataset.id)+'/supervisor','POST',{decision:el.dataset.supervisor});toast('Supervisor decision recorded');await render();return showCase(el.dataset.id)};if(el.dataset.user){await api('/team/'+encodeURIComponent(el.dataset.user),'PATCH',{active:el.dataset.active==='true'});toast('Account access updated');return render()};if(el.dataset.profile){const p=state.profiles.find(x=>x.id===el.dataset.profile);modal('Update customer profile',`<form id="profile-form" data-id="${esc(p.id)}"><div class="stack"><div class="field"><label for="profile-name">Customer name</label><input id="profile-name" name="name" value="${esc(p.name)}" required maxlength="80"></div><div class="field"><label for="profile-notes">Notes</label><textarea id="profile-notes" name="notes" maxlength="3000">${esc(p.notes)}</textarea></div></div><div class="form-error" id="form-error"></div><div class="modal-foot"><button class="btn primary" type="submit">Save profile</button></div></form>`)}}catch(err){toast(err.message);el.disabled=false}});
document.addEventListener('input',e=>{if(e.target.id==='case-search')filterCases()});
document.addEventListener('change',async e=>{if(e.target.id==='order-id'){const selected=e.target.selectedOptions[0];$('#amount').value=(Number(selected.dataset.cents)/100).toFixed(2)}if(e.target.id==='doc-kind')$('#doc-customer').disabled=e.target.value==='policy';if(e.target.id==='doc-file'){const file=e.target.files[0];if(file){if(file.size>40000)return toast('Choose a text file smaller than 40 KB');$('#doc-content').value=await file.text();if(!$('#doc-title').value)$('#doc-title').value=file.name.replace(/\.(txt|md)$/i,'')}}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='Tab'&&$('.modal')){const focus=[...$('.modal').querySelectorAll('button,input,select,textarea,a,summary')].filter(x=>!x.disabled);if(!focus.length)return;const first=focus[0],last=focus[focus.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
document.addEventListener('submit',async e=>{e.preventDefault();const f=e.target,submit=f.querySelector('button[type="submit"]'),values=Object.fromEntries(new FormData(f)),error=f.querySelector('.form-error');if(submit)submit.disabled=true;if(error)error.textContent='';try{if(f.id==='mfa-enroll-form'){const d=await api('/auth/mfa/enroll','POST',values);return mfaEnrollment(d)};if(f.id==='mfa-confirm-form'){const d=await api('/auth/mfa/confirm','POST',values);state.csrf=d.csrf;await render();return modal('Save your recovery codes',notice('Store these codes privately. Each works once if you lose your authenticator. They will not be displayed again.')+'<pre>'+esc(d.recovery_codes.join('\n'))+'</pre><button class="btn primary" data-action="close-modal">I saved my codes</button>')};if(f.id==='mfa-verify-form'){const d=await api('/auth/mfa/verify','POST',values);state.csrf=d.csrf;return render()};if(f.id==='auth-form'){const mode=f.dataset.mode;let body=values;if(mode==='setup')body={...values,token:state.setupToken||values.token};if(mode==='invite')body={password:values.password,token:state.inviteToken};if(mode==='team')body={...values,token:state.teamToken};const d=await api('/auth/'+({login:'login',setup:'setup',invite:'accept-invite',team:'accept-team-invite'}[mode]),'POST',body);state.user=d.user;state.csrf=d.csrf;state.setupToken=null;state.inviteToken=null;state.teamToken=null;history.replaceState(null,'',location.pathname+'#overview');state.page='overview';return render()};if(f.id==='new-case-form'){const cents=Math.round(Number(values.amount)*100);const c=await api('/cases','POST',{order_id:values.order_id,amount_cents:cents,reason_code:values.reason_code,message:values.message});closeModal();toast('Case created and assigned');await render();return showCase(c.id)};if(f.id==='document-form'){await api('/knowledge','POST',{title:values.title,content:values.content,kind:values.kind,customer_id:values.kind==='customer'?values.customer_id:null});closeModal();toast(values.kind==='policy'?'Policy submitted for independent review':'Document indexed with provenance');return render()};if(f.id==='search-form'){const results=await api('/knowledge/search','POST',values);$('#search-results').innerHTML=results.map(r=>`<div class="search-result"><div class="section-head"><h3>${esc(r.title)} · v${r.version}</h3><span class="case-id">${esc(r.source_id)}</span></div><p>${esc(r.content)}</p></div>`).join('')||empty('No authorized documents matched.');return};if(f.id==='invite-form'){const result=await api('/team/invites','POST',values);await render();modal('Your invitation is ready',`${notice('Share this private, single-use link with the intended teammate. It expires in 48 hours. No email was sent.')}<div class="spacer"></div><div class="field"><label for="invite-url">Private invitation link</label><input id="invite-url" readonly value="${esc(result.url)}"></div><div class="modal-foot"><button class="btn primary" data-action="copy-invite">Copy invitation</button></div>`);return};if(f.id==='password-form'){const d=await api('/auth/password','POST',values);state.csrf=d.csrf;f.reset();toast('Password updated. Other sessions were ended.');return};if(f.id==='order-form'){await api('/orders','POST',{customer_id:values.customer_id,product:values.product,amount_cents:Math.round(Number(values.amount)*100),age_days:Number(values.age_days)});closeModal();toast('Synthetic purchase created');return render()};if(f.id==='message-form'){const id=f.dataset.id;await api('/cases/'+encodeURIComponent(id)+'/messages','POST',values);toast('Incoming mock email received');return showCase(id)};if(f.id==='profile-form'){await api('/profiles/'+encodeURIComponent(f.dataset.id),'PATCH',values);closeModal();toast('Profile updated and reindexed');return render()}}catch(err){if(error)error.textContent=err.message;else toast(err.message)}finally{if(submit)submit.disabled=false}});
window.addEventListener('hashchange',()=>{if(location.hash.startsWith('#team-invite=')||location.hash.startsWith('#invite='))return init();if(state.user){state.page=location.hash.slice(1)||'overview';closeModal();render()}});
async function init(){const hash=new URLSearchParams(location.hash.slice(1));state.teamToken=hash.get('team-invite');state.setupToken=hash.get('setup');state.inviteToken=hash.get('invite');if(state.setupToken||state.inviteToken||state.teamToken)history.replaceState(null,'',location.pathname);if(state.teamToken){try{state.teamInvite=await api('/auth/team-invite-status','POST',{token:state.teamToken});return authScreen('team')}catch(e){authScreen('login');$('#auth-error').textContent=e.message;return}}if(state.inviteToken)return authScreen('invite');try{const d=await api('/auth/me');state.user=d.user;state.csrf=d.csrf;state.mode=d.mode;state.authority=d.authority_active;state.page=location.hash.slice(1)||'overview';return render()}catch{}try{const s=await api('/auth/status');authScreen(s.setup_required?'setup':'login')}catch{$('#app').innerHTML='<div class="initial-loading"><h2>The workspace is unavailable</h2><p class="subtitle">Start the local server, then refresh this page.</p></div>'}}

function mfaScreen(enabled){
  $('#app').innerHTML=`<main class="auth-layout"><section class="auth-story">${brand()}<div class="auth-copy"><h1>One more<br><span>layer of care.</span></h1><p>Protect your account and the team's refund controls.</p></div></section><section class="auth-main"><div class="auth-form-wrap"><h2>${enabled?'Verify your sign-in':'Set up your authenticator'}</h2><p>${enabled?'Enter your current six-digit authenticator code or a single-use recovery code.':'Administrators and supervisors must enable MFA on the hosted workspace. Confirm your password to begin.'}</p><form id="${enabled?'mfa-verify-form':'mfa-enroll-form'}"><div class="field"><label for="mfa-input">${enabled?'Verification or recovery code':'Current password'}</label><input id="mfa-input" name="${enabled?'code':'password'}" type="${enabled?'text':'password'}" autocomplete="${enabled?'one-time-code':'current-password'}" required maxlength="${enabled?'80':'128'}"></div><div class="form-error"></div><button class="btn primary" type="submit">${enabled?'Verify':'Begin setup'}</button></form><div class="spacer"></div><button class="btn" data-action="logout">Sign out</button></div></section></main>`;
}
function mfaEnrollment(d){
  $('.auth-form-wrap').innerHTML=`<h2>Add RefundGuard to your authenticator</h2><p>In your authenticator app, choose “Enter a setup key”, select time-based codes, and enter this private key. Setup expires in ten minutes.</p><pre class="request-details">${esc(d.secret)}</pre><form id="mfa-confirm-form"><div class="field"><label for="confirm-code">Current six-digit code</label><input id="confirm-code" name="code" autocomplete="one-time-code" inputmode="numeric" pattern="[0-9]{6}" required maxlength="6"></div><div class="form-error"></div><button class="btn primary" type="submit">Enable MFA</button></form>`;
}
function policyActions(d){
  if(!canControl()||d.kind!=='policy')return '';
  if(d.created_by===state.user.id&&!d.active)return '<p class="cell-secondary">A different administrator or supervisor must review your policy.</p>';
  const button=(action,label)=>`<button class="btn small" data-policy="${esc(d.id)}" data-review="${action}">${label}</button>`;
  return d.review_status==='pending'?`<div class="button-row">${button('publish','Approve and publish')}${button('reject','Reject')}</div>`:d.review_status==='approved'&&!d.active?button('rollback','Restore this version'):'';
}
async function securityPanel(){
  const alerts=await api('/security/alerts');
  return `<div class="spacer"></div><section class="panel panel-pad"><div class="section-head"><h2>Security alerts</h2><a class="btn small" href="/api/security/export" download>Export signed security evidence</a></div>${notice('Alerts are grouped into 15-minute windows. Signed exports detect changes after capture; retain copies separately from the app. Hosting logs must be forwarded separately for independent retention.')}<div class="spacer"></div>${alerts.length?alerts.map(a=>`<div class="event"><div><span class="badge ${a.severity==='high'?'denied':'review'}">${esc(a.severity)}</span></div><div><h3>${esc(a.action)}</h3><small>${a.occurrences} event(s) · ${date(a.last_seen)} ${clock(a.last_seen)}</small>${a.acknowledged_at?'<p>Acknowledged</p>':`<button class="text-link" data-action="ack-alert" data-id="${a.id}">Acknowledge</button>`}</div></div>`).join(''):empty('No security alerts recorded.')}</section>`;
}
function showAdminLink(d){
  modal('Shared administrator invitation',notice('Anyone holding this link can create an administrator account with their own name, email and password. Share privately. Four signups maximum; expires in 48 hours. Administrators must enroll in MFA on the hosted app.',true)+`<div class="field"><label for="invite-url">Private invitation link</label><input id="invite-url" readonly value="${esc(d.url)}"></div><button class="btn primary" data-action="copy-invite">Copy invitation</button>`);
}
document.addEventListener('click',async e=>{
  const policy=e.target.closest('[data-policy]');if(!policy)return;
  policy.disabled=true;try{await api('/knowledge/'+encodeURIComponent(policy.dataset.policy)+'/review','POST',{action:policy.dataset.review});closeModal();toast('Policy review recorded');await render()}catch(err){toast(err.message);policy.disabled=false}
});
init();
